    // Reads one argument. Objects and arrays may arrive JSON-encoded as strings.
    private static T Arg<T>(JObject args, string name, T fallback, bool required)
    {
        var token = args[name];
        if (token == null || token.Type == JTokenType.Null ||
            (token.Type == JTokenType.String && token.ToString().Length == 0 && typeof(T) != typeof(string)))
        {
            if (required) throw new ArgumentException($"Missing required parameter: {name}");
            return fallback;
        }
        if (token.Type == JTokenType.String && typeof(T) != typeof(string))
        {
            var text = token.ToString().Trim();
            if (text.StartsWith("{") || text.StartsWith("["))
                token = JToken.Parse(text);
        }
        return token.ToObject<T>();
    }
